	mustRegister(t, store, "gip-�", 100, "transfer:audits:10")
	mustRegister(t, store, "gip-ok", 100, "transfer:legal:5")
	before, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read state: %v", err)
	}

